TLM.f("Sancti/06-28r",{"officium":"In Vigilia Ss. Petri et Pauli Apostolorum","rule":["ex C1a;","no Gloria","Suffr=Maria3;Ecclesiæ,Papa;;"],"ruleInherited":["Psalmi Dominica","Antiphonas horas","Psalm5 Vespera=116","Psalm5 Vespera3=138"],"fallback":"Commune/C1a","sections":{"Introitus":[{"k":"ref","la":"Joannes 21:18-19"},{"k":"text","la":"Dicit Dóminus Petro: Cum esses júnior, cingébas te et ambulábas, ubi volébas: cum autem senúeris, exténdes manus tuas, et álius te cinget et ducet, quo tu non vis: hoc autem dixit, signíficans, qua morte clarificatúrus esset."},{"k":"ref","la":"Ps 18:2"},{"k":"text","la":"Cœli enárrant glóriam Dei: et ópera mánuum ejus annúntiat firmaméntum."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dicit Dóminus Petro: Cum esses júnior, cingébas te et ambulábas, ubi volébas: cum autem senúeris, exténdes manus tuas, et álius te cinget et ducet, quo tu non vis: hoc autem dixit, signíficans, qua morte clarificatúrus esset."}],"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut nullis nos permíttas perturbatiónibus cóncuti; quos in apostólicæ confessiónis petra solidásti."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Actuum Apostolórum"},{"k":"ref","la":"Act 3:1-10"},{"k":"text","la":"In diébus illis: Petrus et Joánnes ascendébant in templum ad horam oratiónis nonam. Et quidam vir, qui erat claudus ex útero matris suæ, bajulabátur: quem ponébant cotídie ad portam templi, quæ dícitur Speciósa, ut péteret eleemósynam ab introeúntibus in templum. Is cum vidísset Petrum et Joánnem incipiéntes introíre in templum, rogábat, ut eleemósynam acciperet. Intuens autem in eum Petrus cum Joánne, dixit: Réspice in nos. At ille intendébat in eos, sperans se áliquid acceptúrum ab eis. Petrus autem dixit: Argéntum et aurum non est mihi; quod autem habeo, hoc tibi do: In nómine Jesu Christi Nazaréni surge, et ámbula. Et apprehénsa manu ejus déxtera, allevávit eum, et protínus consolidátæ sunt bases ejus et plantæ. Et exsíliens stetit, et ambulábat: et intrávit cum illis in templum, ámbulans et exsíliens et laudans Deum. Et vidit omnis populus eum ambulántem et laudántem Deum. Cognoscébant autem illum, quod ipse erat, qui ad eleemósynam sedébat ad Speciósam portam templi: et impléti sunt stupore et écstasi in eo, quod contígerat illi."}],"Graduale":[{"k":"ref","la":"Ps 18:5; 18:2"},{"k":"text","la":"In omnem terram exívit sonus eórum: et in fines orbis terræ verba eórum."},{"k":"text","la":"Cœli enárrant glóriam Dei: et ópera mánuum ejus annúntiat firmaméntum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 21:15-10"},{"k":"text","la":"In illo témpore: Dixit Jesus Simóni Petro: Simon Joánnis, díligis me plus his? Dicit ei: Etiam, Dómine, tu scis, quia amo te. Dicit ei: Pasce agnos meos. Dicit ei íterum: Simon Joánnis, díligis me? Ait illi: Etiam, Dómine, tu scis, quia amo te. Dicit ei: Pasce agnos meos. Dicit ei tértio: Simon Joánnis, amas me? Contristátus est Petrus, quia dixit ei tértio, Amas me? et dixit ei: Dómine, tu ómnia nosti: tu scis, quia amo te. Dixit ei: Pasce oves meas. Amen, amen, dico tibi: cum esses júnior, cingébas te et ambulábas, ubi volébas: cum autem senúeris, exténdes manus tuas, et álius te cinget et ducet, quo tu non vis. Hoc autem dixit, signíficans, qua morte clarificatúrus esset Deum."}],"Offertorium":[{"k":"ref","la":"Ps 138:17"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."}],"Secreta":[{"k":"text","la":"Munus pópuli tui, quǽsumus, Dómine, apostólica intercessióne sanctífica: nosque a peccatórum nostrórum máculis emúnda."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joannes 21:15; 21:17"},{"k":"text","la":"Simon Joánnis, díligis me plus his? Dómine, tu ómnia nosti: tu scis, Dómine, quia amo te."}],"Postcommunio":[{"k":"text","la":"Quos cœlésti, Dómine, aliménto satiásti: apostólicis intercessiónibus ab omni adversitáte custódi."},{"k":"macro","name":"Per Dominum"}]},"hr":{"88fdbb674deab6d7":{"t":"Iv 21, 18-19, Ps 18, 1\n(Iv 21, 18-19) Gospodin reče Petru: Dok si bio mladi, opasivao si se sam i hodao kuda si htio, a kad ostariš raširit ćeš svoje ruke i drugi će te opasivati i odvesti kuda ti nećeš. Ovim je riječima htio označiti kakvom će smrću proslaviti Boga. (Ps 18, 1). Nebesa pripovijedaju slavu Božju i nebeski svod naviješćuje djelo njegovih ruku.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iv 21, 18-19) Gospodin reče Petru: Dok si bio mladi, opasivao si se sam i hodao kuda si htio, a kad ostariš raširit ćeš svoje ruke i drugi će te opasivati i odvesti kuda ti nećeš. Ovim je riječima htio označiti kakvom će smrću proslaviti Boga.","v":"deum → ∅; deum → ∅"},"182c76715243c887":{"t":"<i>Pomolimo se</i>.\nNe dopusti, molimo, svemogući Bože, da nas ikakvi neredi straše, kad si nas utvrdio na stijeni apostolskog priznavanja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"c86c7d5ad27bd3a4":{"t":"Dj 3, 1-10\nČitanje Djela apostolskih. U one dane Petar i Ivan išli su u hram u deveti čas molitve. I bio je jedan čovjek hrom od rođenja koga su nosili i svaki dan stavljali pred hramska vrata koja se zovu Krasna, da prosi milostinju od onih koji ulaze u hram. Kad je on vidio Petra i Ivana gdje hoće da uđu u hram, zamoli milostinju. A Petar zajedno s Ivanom pogleda na nj i reče: Pogledaj na nas! On pogleda na njih nadajući se da će što od njih dobiti. A Petar reče: Nemam srebra ni zlata, ali što imam evo ti dajem: U ime Isusa Krista Nazarećanina ustani i hodi! I uze ga za desnu ruku i podiže ga. Odmah se utvrdiše njegova stopala i gležnji. I skoči te je mogao stajati i hodati. I ude s njima u hram idući i skačući i hvaleći Boga. Sav je narod vidio gdje ide i hvali Boga. I prepoznali su ga da je on onaj koji je bio sjedio radi milostinje kod Krasnih vrata hrama. I napuniše se čuđenja i udivljenja za ovo što mu se dogodilo."},"6b6fd9208cef1e6d":{"t":"Ps 18, 5 et 2\nPo svoj zemlji iziđe njihov glas, i do na kraj svijeta njihova nauka. Nebesa pripovijedaju slavu Božju i svod nebeski naviješta djelo njegovih ruku."},"dca7b2b49947ab9a":{"t":"Iv 21, 15-19\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme reče Isus Šimunu Petru: Šimune Ivanov, ljubiš li me više nego ovi? Reče mu: Da, Gospodine, ti znaš da te ljubim. Reče mu: Pasi jaganjče moje! Reče mu opet drugi put: Šimune Ivanov, ljubiš li me? Odgovori mu: Da, Gospodine, ti znaš da te ljubim. Reče mu: Pasi jaganjče moje! Reče mu treći put: Šimune Ivanov, ljubiš li me? Ožalosti se Petar što ga po treći put pita: Ljubiš li me? I odgovori mu: Gospodine, ti sve znaš, ti znaš da te ljubim. Reče mu Isus: Pasi ovce moje! Zaista, zaista ti kažem: Dok si bio mlađi, opasivao si se sam i hodao si kuda si htio; a kad ostariš raširit ćeš svoje ruke i drugi će te opasivati i odvesti kuda ti nećeš. A ovim je riječima htio označiti kakvom će smrću proslaviti Boga."},"8bade162dbdb175e":{"t":"Ps 138, 17\nNada sve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove."},"63e703350a97d2ac":{"t":"Posveti, Gospodine, po apostolskom zagovoru dar svoga naroda i očisti nas od ljaga naših grijeha.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"5bbe39aadec34150":{"t":"Iv 21, 15 i 17\nŠimune Ivanov, ljubiš li me više nego ovi? Gospodine, ti sve znaš, ti znaš da te ljubim."},"d264ead8fb5621e7":{"t":"<i>Pomolimo se</i>.\nGospodine, po apostolskom zagovoru čuvaj od svake protivštine nas koje si nasitio nebeskom hranom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
